namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
    }

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day right with these morning favorites" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals that are quick and satisfying" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats to finish any meal" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    private static List<Recipe> GetSeedRecipes() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy buttermilk pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups all-purpose flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp baking soda", "1/2 tsp salt", "2 cups buttermilk", "2 eggs", "1/4 cup melted butter"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk buttermilk, eggs, and melted butter together.", "Pour wet ingredients into dry and stir until just combined.", "Heat a griddle over medium heat and grease lightly.", "Pour 1/4 cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown. Serve with maple syrup."],
            TotalRatings = 12, RatingSum = 50
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple yet delicious avocado toast with a perfect seasoning blend.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes", "1 tbsp olive oil"],
            Steps = ["Toast the bread until golden and crispy.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread the avocado mixture on the toast.", "Drizzle with olive oil and sprinkle red pepper flakes.", "Serve immediately."],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp and creamy classic Caesar salad with homemade dressing.",
            Ingredients = ["1 head romaine lettuce", "1/2 cup croutons", "1/4 cup parmesan cheese", "2 tbsp Caesar dressing", "1 lemon", "Salt and pepper"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze lemon over the top.", "Season with salt and pepper. Serve chilled."],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch",
            Description = "A protein-packed wrap with grilled chicken and fresh vegetables.",
            Ingredients = ["2 chicken breasts", "4 large tortillas", "1 cup mixed greens", "1 tomato, diced", "1/4 cup ranch dressing", "Salt and pepper"],
            Steps = ["Season chicken with salt and pepper, then grill until cooked through.", "Slice chicken into strips.", "Warm tortillas on the grill.", "Layer greens, chicken, tomato, and ranch on each tortilla.", "Roll tightly and slice in half. Serve."],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 5, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian classic with slow-simmered meat sauce.",
            Ingredients = ["1 lb spaghetti", "1 lb ground beef", "1 onion, diced", "3 cloves garlic", "1 can crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper", "Parmesan cheese"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, then drain fat.", "Sauté onion and garlic until softened.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer sauce for 20 minutes, stirring occasionally.", "Toss pasta with sauce and serve with parmesan."],
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 6, Title = "Chicken Stir-Fry", Category = "Dinner",
            Description = "A quick and colorful weeknight stir-fry loaded with vegetables.",
            Ingredients = ["2 chicken breasts, sliced", "1 bell pepper, sliced", "1 cup broccoli florets", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic", "Cooked rice"],
            Steps = ["Mix soy sauce, sesame oil, and cornstarch for the sauce.", "Heat oil in a wok over high heat.", "Cook chicken until golden, then remove.", "Stir-fry vegetables and garlic for 3 minutes.", "Return chicken and pour sauce over everything.", "Toss until coated and serve over rice."],
            TotalRatings = 9, RatingSum = 38
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Chewy, golden chocolate chip cookies that melt in your mouth.",
            Ingredients = ["2 1/4 cups flour", "1 cup butter, softened", "3/4 cup sugar", "3/4 cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "2 cups chocolate chips"],
            Steps = ["Preheat oven to 375°F.", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet and bake 9-11 minutes."],
            TotalRatings = 20, RatingSum = 92
        },
        new()
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Description = "An elegant Italian dessert layered with espresso-soaked ladyfingers.",
            Ingredients = ["6 egg yolks", "3/4 cup sugar", "1 1/4 cups mascarpone", "2 cups heavy cream", "2 cups espresso, cooled", "24 ladyfinger cookies", "Cocoa powder"],
            Steps = ["Whisk egg yolks and sugar over a double boiler until thick.", "Remove from heat and fold in mascarpone.", "Whip heavy cream to stiff peaks and fold into mascarpone mixture.", "Dip ladyfingers briefly in espresso.", "Layer cookies and cream mixture in a dish.", "Refrigerate 4 hours, then dust with cocoa powder."],
            TotalRatings = 14, RatingSum = 65
        },
        new()
        {
            Id = 9, Title = "Trail Mix", Category = "Snacks",
            Description = "A customizable energy-boosting snack for hikes or afternoon breaks.",
            Ingredients = ["1 cup mixed nuts", "1/2 cup raisins", "1/2 cup M&Ms or chocolate chips", "1/4 cup sunflower seeds", "1/4 cup dried cranberries"],
            Steps = ["Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Divide into snack-size portions.", "Store in airtight bags or containers."],
            TotalRatings = 5, RatingSum = 20
        },
        new()
        {
            Id = 10, Title = "Guacamole", Category = "Snacks",
            Description = "Fresh and zesty guacamole, perfect with tortilla chips.",
            Ingredients = ["3 ripe avocados", "1 lime, juiced", "1/2 tsp salt", "1/2 cup diced onion", "1 jalapeño, minced", "2 tbsp cilantro", "1 diced tomato"],
            Steps = ["Mash avocados in a bowl to desired consistency.", "Stir in lime juice and salt.", "Mix in onion, jalapeño, cilantro, and tomato.", "Taste and adjust seasoning.", "Serve immediately with tortilla chips."],
            TotalRatings = 11, RatingSum = 48
        },
    ];
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              title="Rate @star star(s)">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="rating-feedback">Thanks for rating!</span>
    }
    <span class="rating-info">(@TotalRatings ratings, avg @AverageRating.ToString("F1"))</span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public int TotalRatings { get; set; }
    [Parameter] public double AverageRating { get; set; }

    private int currentRating;
    private int hoverRating;
    private bool submitted;

    private void Rate(int stars)
    {
        if (submitted) return;
        currentRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            TotalRatings = recipe.TotalRatings;
            AverageRating = recipe.AverageRating;
        }
    }
}

