@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@{ var category = RecipeService.GetCategories().FirstOrDefault(c => c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase)); }

@if (category is not null)
{
    <h1>@category.Icon @category.Name Recipes</h1>
    <p class="lead">@category.Description</p>
}
else
{
    <h1>@CategoryName Recipes</h1>
}

@{ var recipes = RecipeService.GetRecipesByCategory(CategoryName); }

@if (recipes.Count == 0)
{
    <div class="alert alert-info mt-3">
        No recipes found in this category yet. <a href="submit">Be the first to submit one!</a>
    </div>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in recipes)
